<?php
declare(strict_types=1);namespace QualitySystem\Repositories;use PDO;use QualitySystem\Domain\CourseReport\CourseReport;
final class CourseReportRepository{
public const EDITABLE=['course_specification_id','course_code','course_title','academic_year','semester','course_coordinator','students_enrolled','students_passed','students_failed','clo_achievement_summary','assessment_summary','teaching_summary','student_feedback_summary','course_improvement_actions','general_notes','status','department_name','program_name','college_name','institution_name','course_instructors','location','number_of_sections','students_starting','students_completed','report_date','report_version','created_by_user_id'];
public function __construct(private readonly PDO $pdo){}
private function scope(string $role,int $user,array &$p,string $a='cr'):string{if(in_array($role,['Admin','Quality Coordinator'],true))return'1=1';$p[':report_user']=$user;$p[':report_program_user']=$user;return"($a.created_by_user_id=:report_user OR EXISTS(SELECT 1 FROM course_specifications csx JOIN user_program_access upa ON upa.program_specification_id=csx.program_specification_id WHERE csx.id=$a.course_specification_id AND upa.user_id=:report_program_user))";}
public function paginate(string $role,int $user,int $page,int $limit,array $f):array{$p=[];$w=$this->scope($role,$user,$p);if($f['search']!==''){$w.=' AND (cr.course_code LIKE :search OR cr.course_title LIKE :search OR cr.course_coordinator LIKE :search)';$p[':search']='%'.$f['search'].'%';}foreach(['academic_year','semester','status']as$x)if($f[$x]!==''){$w.=" AND cr.$x=:$x";$p[":$x"]=$f[$x];}$c=$this->pdo->prepare("SELECT COUNT(*) FROM course_reports cr WHERE $w");$c->execute($p);$s=$this->pdo->prepare("SELECT cr.*,cs.program_specification_id,cs.version_no FROM course_reports cr LEFT JOIN course_specifications cs ON cs.id=cr.course_specification_id WHERE $w ORDER BY cr.id DESC LIMIT :limit OFFSET :offset");foreach($p as$k=>$v)$s->bindValue($k,$v);$s->bindValue(':limit',$limit,PDO::PARAM_INT);$s->bindValue(':offset',($page-1)*$limit,PDO::PARAM_INT);$s->execute();return['rows'=>$s->fetchAll(PDO::FETCH_ASSOC),'total'=>(int)$c->fetchColumn()];}
public function findScoped(int$id,string$role,int$user):?array{$p=[':id'=>$id];$w=$this->scope($role,$user,$p);$s=$this->pdo->prepare("SELECT cr.* FROM course_reports cr WHERE cr.id=:id AND $w LIMIT 1");$s->execute($p);return$s->fetch(PDO::FETCH_ASSOC)?:null;}
public function courseSpecifications(string$role,int$user):array{$p=[];$w=in_array($role,['Admin','Quality Coordinator'],true)?'1=1':'cs.program_specification_id IN(SELECT program_specification_id FROM user_program_access WHERE user_id=:user)';if(!in_array($role,['Admin','Quality Coordinator'],true))$p[':user']=$user;$s=$this->pdo->prepare("SELECT cs.id,cs.course_code,cs.course_title,cs.program_name,cs.department_name,cs.college_name,cs.institution_name FROM course_specifications cs WHERE $w ORDER BY cs.course_code LIMIT 500");$s->execute($p);return$s->fetchAll(PDO::FETCH_ASSOC);}
public function specification(int$id):?array{$s=$this->pdo->prepare('SELECT * FROM course_specifications WHERE id=:id LIMIT 1');$s->execute([':id'=>$id]);return$s->fetch(PDO::FETCH_ASSOC)?:null;}
public function save(CourseReport$r):int{$f=array_intersect_key($r->fields,array_flip(self::EDITABLE));$a=[];$p=[];foreach($f as$k=>$v){$a[]="`$k`=:$k";$p[":$k"]=$v;}if($r->id===null){$this->pdo->prepare('INSERT INTO course_reports SET '.implode(',',$a))->execute($p);return(int)$this->pdo->lastInsertId();}$p[':id']=$r->id;$this->pdo->prepare('UPDATE course_reports SET '.implode(',',$a).' WHERE id=:id')->execute($p);return$r->id;}
public function delete(int$id):void{$this->pdo->prepare('DELETE FROM semester_report_course_reports WHERE course_report_id=:id')->execute([':id'=>$id]);$this->pdo->prepare('DELETE FROM course_reports WHERE id=:id')->execute([':id'=>$id]);}}
